$ErrorActionPreference='Stop'
$project=Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'evidence-json.ps1')
$logs=Join-Path $project 'logs\continuation-20261003'
function Pin($p){[ordered]@{path=$p;bytes=(Get-Item -LiteralPath $p).Length;sha256=(Get-FileHash -LiteralPath $p).Hash}}
$s=Get-Content (Join-Path $logs 'r473-resource-snapshot.json') -Raw|ConvertFrom-Json
$inventory=@(foreach($pair in $s.pairs){$out=Join-Path $s.root ($pair.id+'-complete');$ledger=Join-Path $out 'all-members.tsv';$rows=@(Get-Content $ledger|ForEach-Object{$v=$_.Split("`t");[ordered]@{record_index=[int]$v[0];name=$v[1];offset=[long]$v[2];bytes=[long]$v[3];duplicate=$v[4] -eq 'true'}});$campaign=@(foreach($row in $rows|Where-Object{$_.name -like 'campaignDesc*'}){$raw=Join-Path $out ($row.name+'.raw');$decoded=Join-Path $out ($row.name+'.decoded');[ordered]@{record_index=$row.record_index;name=$row.name;offset=$row.offset;bytes=$row.bytes;raw=Pin $raw;decoded=Pin $decoded}});[ordered]@{id=$pair.id;namespace=$pair.namespace;archives=$pair.archives;index_count=$rows.Count;duplicate_rows=@($rows|Where-Object{$_.duplicate}).Count;duplicate_groups=@($rows|Group-Object { $_.name }|Where-Object{$_.Count -gt 1}|ForEach-Object{[ordered]@{name=$_.Name;records=$_.Group}});complete_inventory=Pin $ledger;decoded_index=Pin (Join-Path $out 'decoded-index.bin');campaign_members=$campaign;inspector_stdout=Pin (Join-Path $logs ('r473b-'+$pair.id+'-inventory.stdout.log'));inspector_stderr=Pin (Join-Path $logs ('r473b-'+$pair.id+'-inventory.stderr.log'))}})
if(!(Test-Path (Join-Path $logs 'r473-complete-campaign-inventory.json'))){Write-ModernEvidenceJson -Path (Join-Path $logs 'r473-complete-campaign-inventory.json') -Value ([ordered]@{state='FULL_75140_MEMBER_ROWS_THREE_PAIRS_10_CAMPAIGN_MEMBERS_5_VARIANTS_NO_AMBIGUITY';resource_snapshot=Pin (Join-Path $logs 'r473-resource-snapshot.json');pairs=$inventory;total_rows=($inventory.index_count|Measure-Object -Sum).Sum;resource_namespace_not_live_loaded_grant=$true;cipher=Pin (Join-Path $project 'src\modern_lito\resource_cipher.rs');inspector=Pin (Join-Path $s.root 'inspect-r473b-campaign.exe');inspector_source=Pin (Join-Path $project 'tools\inspect-r473-campaign.rs');failed_inventory_preserved=Pin (Join-Path $logs 'r473a-inventory-failure-preservation.json');renderer_LOADED=$false;GUI=0})}
$prior=Get-Content (Join-Path $logs 'r472-original-source-pins.json') -Raw|ConvertFrom-Json;$gap=Get-Content (Join-Path $logs 'r472-campaign-global-producer-gap.json') -Raw|ConvertFrom-Json;$text=[IO.File]::ReadAllText($prior.original_disassembly.path)
$root=Join-Path $project 'target\r473b-campaign-table-source-contract';if(Test-Path $root){throw 'Already frozen'};[IO.Directory]::CreateDirectory($root)|Out-Null
$seen=@{};$files=@(foreach($p in @($prior.files)+@($gap.declared_bodies)){if(!$seen.ContainsKey($p.sha256)){$seen[$p.sha256]=$true;$dst=Join-Path $root (Split-Path $p.path -Leaf);[IO.File]::Copy($p.path,$dst,$false);Pin $dst}})
foreach($name in @('43DCC0','42E8F0','42E6F0','42E710')){$m=[regex]::Matches($text,'(?ms)^sub_'+$name+' proc near.*?^sub_'+$name+' endp[^\r\n]*');if($m.Count -ne 1){throw 'Source count'};$p=Join-Path $root ("sub_$name.asm");[IO.File]::WriteAllText($p,$m[0].Value,[Text.UTF8Encoding]::new($false));$pin=Pin $p;if(!$seen.ContainsKey($pin.sha256)){$files+=,$pin;$seen[$pin.sha256]=$true}}
$fragments=@(foreach($p in @($prior.fragments)+@($gap.exact_fragments)){$dst=Join-Path $root (Split-Path $p.path -Leaf);[IO.File]::Copy($p.path,$dst,$false);Pin $dst})
foreach($spec in @(@('language-switch-tables','^jpt_4D43E7 dd.*?(?=^align 10h)'),@('baseText-reader647980-initialize','^loc_42EC9F:.*?(?=^loc_42ECBA:)'))){$m=[regex]::Matches($text,'(?ms)'+$spec[1]);if($m.Count -ne 1){throw ('Fragment count '+$spec[0])};$p=Join-Path $root ($spec[0]+'.asm-fragment');[IO.File]::WriteAllText($p,$m[0].Value,[Text.UTF8Encoding]::new($false));$fragments+=,(Pin $p)}
Write-ModernEvidenceJson -Path (Join-Path $logs 'r473-original-source-pins.json') -Value ([ordered]@{original_disassembly=$prior.original_disassembly;files=$files;fragments=$fragments;static_decode=$prior.static_decode;declared_endp_not_completeCFG=$true;native_executed=$false})
Write-Output "Complete inventory fixed; source $($files.Count) bodies/$($fragments.Count) fragments"
